-- 셋을 나란히 만든다

// ① 통제 — 안 부를 수 있다
public class PermissionProxy implements OrderService {
    private final OrderService target;

    @Override
    public void orderItem(String itemId) {
        if (!currentUser().hasRole("USER")) {
            log.warn("막았다 user={}", currentUser().name());
            throw new AccessDeniedException("권한 없음");
        }
        target.orderItem(itemId);
    }
}

// ② 캐시 — 이번만 안 부른다
public class CacheProxy implements OrderService {
    private final OrderService target;
    private final Map<String, String> cache = new ConcurrentHashMap<>();

    @Override
    public String find(String itemId) {
        return cache.computeIfAbsent(itemId, k -> {
            log.info("원본을 부른다 {}", k);
            return target.find(k);
        });
    }
}

// ③ 덧붙이기 — 늘 부른다
public class TraceDecorator implements OrderService {
    private final OrderService target;

    @Override
    public String find(String itemId) {
        TraceStatus status = trace.begin("OrderService.find()");
        String result = target.find(itemId);      // 반드시 부른다
        trace.end(status);
        return result;
    }
}

