@Bean
public OrderService orderService(LogTrace trace) {
    OrderService target = new OrderServiceImpl(orderRepository(trace));
    OrderService a = new TraceDecorator(target, trace);
    OrderService b = new UpperDecorator(a);
    OrderService c = new PrefixDecorator(b, "[상품] ");
    return c;
}

