@Bean
public OrderService orderService(LogTrace trace) {
    OrderService s = new OrderServiceImpl(orderRepository(trace));
    s = new TraceDecorator(s, trace);
    s = new TimeDecorator(s);
    s = new UpperDecorator(s);
    s = new PrefixDecorator(s, "[상품] ");
    s = new CacheProxy(s);
    return s;
}

